/* 初級用フラッシュ暗算 Service Worker — version-linked cache.
   Bump APP_VERSION together with the app version; old caches are
   deleted on activate so a new release never sticks to an old cache. */
var APP_VERSION = "20261124-1";
var CACHE = "shokyu-flash-v" + APP_VERSION;
var ASSETS = [
  "./",
  "./index.html",
  "./manifest.webmanifest",
  "./icon.svg"
];

self.addEventListener("install", function (e) {
  e.waitUntil(
    caches.open(CACHE).then(function (c) { return c.addAll(ASSETS); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener("activate", function (e) {
  e.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.map(function (k) {
        if (k !== CACHE) return caches.delete(k);
      }));
    }).then(function () { return self.clients.claim(); })
  );
});


/* アイコンPNGは push の都合 (UTF-8テキストのみ) でサーバに置けないので、
   SW が内蔵 base64 から合成して返す (くくダッシュと同じ方式)。
   実ファイルとして置ける icon.svg は ASSETS に入れて通常配信する。 */
var ICON_B64 = {"icon-192.png": "", "icon-180.png": "", "icon-512.png": ""};
function iconResponse(b64){
  var bin = atob(b64);
  var bytes = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { "Content-Type": "image/png" } });
}

self.addEventListener("fetch", function (e) {
  if (e.request.method !== "GET") return;

  // アイコンPNGへのリクエストは内蔵データから合成して返す
  var iconPath = new URL(e.request.url).pathname;
  for (var iconName in ICON_B64) {
    if (iconPath.slice(-iconName.length) === iconName) {
      e.respondWith(iconResponse(ICON_B64[iconName]));
      return;
    }
  }
  e.respondWith(
    caches.match(e.request, { ignoreSearch: true }).then(function (hit) {
      if (hit) return hit;
      return fetch(e.request).then(function (res) {
        var copy = res.clone();
        caches.open(CACHE).then(function (c) { c.put(e.request, copy); });
        return res;
      }).catch(function () {
        if (e.request.mode === "navigate") return caches.match("./index.html");
        throw new Error("offline and not cached");
      });
    })
  );
});
